import {samples,predict,trainThreshold,defaultCorpus,trainBigram,distribution,sampleToken} from './ai-models.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const concepts={AI:'สาขาที่สร้างระบบทำงานด้านการรับรู้ การเรียนรู้ และการตัดสินใจ รวมวิธีที่ไม่ใช่ ML',ML:'วิธีเรียนรู้รูปแบบหรือพารามิเตอร์จากข้อมูล เป็นส่วนหนึ่งของ AI',DL:'ส่วนหนึ่งของ ML ที่ใช้ Neural Network หลายชั้น',NLP:'กลุ่มงานด้านภาษา เช่น แปล สรุป และจำแนกข้อความ ใช้กฎหรือ ML/DL ก็ได้',GenAI:'งานสร้างเนื้อหา เช่น ข้อความ ภาพ หรือเสียง ไม่ใช่แค่การจัดหมวดหมู่',LLM:'โมเดลภาษาขนาดใหญ่ สมัยใหม่ใช้ DL; แบบสร้างข้อความเกี่ยวข้องกับ NLP และ GenAI'};
export function aiPreview(l){const text=l.id==='ai-map'?'AI ⊃ ML ⊃ DL':l.id==='ai-rules'?'กฎของคน ↔ ข้อมูลฝึก':l.id==='ai-training'?'DATA → TRAIN → MODEL': 'ฉัน → ชอบ → ชา';return `<div class="ai-preview"><span>${text}</span><small>${esc(l.subtitle)}</small></div>`;}
export function aiSurface(l){
 const map=l.id==='ai-map';
 return `<section class="ai-lab" aria-label="ห้องทดลอง AI"><header><p class="eyebrow">AI · VISUAL INTERACTIVE</p><h2>${esc(l.subtitle)}</h2><p>${map?'แผนที่เชิงแนวคิด ไม่ใช่โครงสร้างของโมเดลจริง':'คำนวณจริงในโมเดลจิ๋วบนเครื่องคุณ · ไม่เรียก API และไม่ส่งข้อมูลออก'}</p></header><div class="ai-mission"><strong>ภารกิจ: ${esc(l.scenario)}</strong><ol>${l.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div><div class="ai-playground">${map?`<div class="ai-map"><div class="ai-nest"><button data-concept="AI">AI</button><div><button data-concept="ML">ML</button><div><button data-concept="DL">DL</button><button data-concept="LLM">LLM สมัยใหม่</button></div></div></div><div class="ai-domains"><button data-concept="NLP">NLP · งานภาษา</button><button data-concept="GenAI">GenAI · สร้างเนื้อหา</button></div></div><p>ขนาดกล่องไม่ได้บอกขนาดตลาดหรือจำนวนโมเดล · ป้ายงานด้านขวาทับซ้อนกับวิธีการได้</p><label>เลือกตัวอย่าง<select id="ai-example"><option value="translate">แปลภาษาด้วยกฎ</option><option value="chat">LLM สร้างข้อความตอบ</option><option value="image">สร้างภาพจากข้อความด้วย diffusion</option></select></label><div id="ai-map-detail" role="status"></div>`:l.id==='ai-tokens'?`<label>ข้อความฝึก · แบ่ง Token ด้วยช่องว่าง บรรทัดละประโยค<textarea id="ai-corpus" maxlength="4000" rows="5">${defaultCorpus}</textarea></label><button class="button" id="ai-train">ฝึก Bigram</button><button class="button light" id="ai-next">สร้าง Token ถัดไป</button><button class="button light" id="ai-restart">เริ่มประโยคใหม่</button><div id="ai-generated" class="ai-generated" aria-live="polite"></div><div id="ai-distribution"></div>`:`<div class="ai-inputs"><label>คะแนนที่ต้องการทำนาย<input id="ai-score" type="number" min="0" max="100" value="65"></label><label>Threshold ของกฎคน<input id="ai-rule" type="number" min="0" max="100" value="70"></label></div><button class="button" id="ai-train">ฝึกจากตัวอย่าง</button>${l.id==='ai-training'?'<button class="button light" id="ai-add">เพิ่มตัวอย่าง 55 → ผ่าน</button>':''}<div id="ai-data"></div><div id="ai-chart"></div><div id="ai-prediction"></div>`}<button class="button light" id="ai-reset">รีเซ็ตทั้งหมด</button><div id="ai-status" role="status" aria-live="polite"></div></div><section class="question-box"><p class="eyebrow">ตรวจความเข้าใจ</p><h3>${esc(l.question)}</h3><div class="choices">${l.choices.map((c,i)=>`<button data-ai-answer="${i}">${esc(c)}</button>`).join('')}</div><button class="hint" id="hint">ขอคำใบ้</button><div class="feedback" id="feedback" aria-live="polite"></div></section></section>`;
}
export function initAI(l,complete){
 const root=document.querySelector('.ai-lab'),q=s=>root.querySelector(s);const initialData=()=>l.id==='ai-rules'?samples().filter(p=>p.x!==60):samples();let data=initialData(),trained=null,bigram=null,words=[],last='<START>',draws=0,seed=42,observed=false,revision=0,trainedRevision=-1;
 const status=text=>q('#ai-status').textContent=text;
 function numeric(id){const el=q(id),v=Number(el.value);if(el.value===''||!Number.isFinite(v)||v<0||v>100)throw Error('กรอกคะแนนและ threshold ระหว่าง 0–100');return v;}
 function renderClassifier(){const score=numeric('#ai-score'),rule=numeric('#ai-rule');q('#ai-data').innerHTML=`<h3>ตัวอย่างฝึก ${data.length} รายการ</h3><p>${data.map(p=>`${p.x} → ${p.y?'ผ่าน':'ไม่ผ่าน'}`).join(' · ')}</p>`;
 q('#ai-chart').innerHTML=`<svg viewBox="0 0 600 140" role="img" aria-label="แกนคะแนน 0 ถึง 100 กฎคน ${rule} โมเดล ${trained?.threshold??'ยังไม่ฝึก'}"><line x1="30" y1="95" x2="570" y2="95" stroke="#9cb8c3"/>${data.map(p=>`<circle cx="${30+p.x*5.4}" cy="${p.y?45:75}" r="8" fill="${p.y?'#7ce4c6':'#efaa91'}"><title>${p.x} ${p.y?'ผ่าน':'ไม่ผ่าน'}</title></circle>`).join('')}<line x1="${30+rule*5.4}" y1="20" x2="${30+rule*5.4}" y2="95" stroke="#ffcb78" stroke-width="3"/>${trained?`<line x1="${30+Math.min(100,trained.threshold)*5.4}" y1="20" x2="${30+Math.min(100,trained.threshold)*5.4}" y2="95" stroke="#80baff" stroke-width="3" stroke-dasharray="5 4"/>`:''}<text x="30" y="120">0</text><text x="550" y="120">100</text></svg><p>จุดสีเขียว = ผ่าน · สีส้ม = ไม่ผ่าน · เส้นเหลือง = กฎคน · เส้นฟ้า = โมเดล</p>`;
 q('#ai-prediction').innerHTML=`<div class="ai-result"><p>กฎคน: ${score} ≥ ${rule} → <strong>${predict(score,rule)?'ผ่าน':'ไม่ผ่าน'}</strong></p><p>โมเดล: ${trained?`${score} ≥ ${trained.threshold} → <strong>${predict(score,trained.threshold)?'ผ่าน':'ไม่ผ่าน'}</strong>`:'ยังไม่ฝึก'}</p>${trained?`<p>ผิดในชุดฝึก ${trained.errors}/${trained.size} · ไม่ใช่คะแนนชุดทดสอบ${trainedRevision!==revision?' · ข้อมูลเปลี่ยนแล้ว ยังใช้โมเดลเดิมจนกดฝึกใหม่':''}</p>`:''}</div>`;
 }
 function renderTokens(){q('#ai-generated').textContent=words.length?words.join(' '):'ยังไม่มีข้อความ — เริ่มที่ <START>';const options=bigram?distribution(bigram,last):[];q('#ai-distribution').innerHTML=`<h3>ตัวเลือกหลัง ${esc(last)}</h3>${options.length?options.map(o=>`<div class="ai-prob"><code>${esc(o.token)}</code><meter min="0" max="1" value="${o.probability}"></meter><span>${o.count} ครั้ง · ${(o.probability*100).toFixed(1)}%</span></div>`).join(''):'<p>ยังไม่ฝึก หรือจบประโยคแล้ว</p>'}`;q('#ai-next').disabled=!options.length||words.length>=30;}
 function mapExample(){const value=q('#ai-example').value,labels=value==='translate'?['AI','NLP']:value==='chat'?['AI','ML','DL','LLM','NLP','GenAI']:['AI','ML','DL','GenAI'];root.querySelectorAll('[data-concept]').forEach(b=>b.classList.toggle('selected',labels.includes(b.dataset.concept)));q('#ai-map-detail').textContent=`${labels.join(' + ')} — ${value==='translate'?'ตัวอย่างนี้กำหนดให้ใช้กฎ ไม่ได้เรียนจากข้อมูล':value==='chat'?'สร้างข้อความด้วย LLM': 'โมเดลสร้างภาพไม่ใช่ LLM; การรับ prompt ภาษาไม่ได้ทำให้ระบบทั้งหมดเป็น NLP อย่างเดียว'}`;observed=true;}
 root.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;try{
 if(button.dataset.concept){status(`${button.dataset.concept}: ${concepts[button.dataset.concept]}`);return;}
 if(button.dataset.aiAnswer!==undefined){const ready=observed&&(l.id==='ai-training'?trainedRevision===revision&&revision>0:l.id==='ai-tokens'?draws>0:true);q('#feedback').textContent=Number(button.dataset.aiAnswer)!==l.answer?'ยังไม่ตรง ลองสังเกตผลในห้องทดลองอีกครั้ง':!ready?'คำตอบถูกแล้ว ลองทำภารกิจในห้องทดลองก่อนเพื่อบันทึกความคืบหน้า':'✓ ผ่าน — '+l.hint;if(Number(button.dataset.aiAnswer)===l.answer&&ready)complete(l.id);return;}
 if(button.id==='hint'){q('#feedback').textContent=l.hint;return;}
 if(button.id==='ai-reset'){data=initialData();trained=null;bigram=null;words=[];last='<START>';draws=0;revision=0;trainedRevision=-1;observed=false;if(l.id==='ai-map'){q('#ai-example').value='translate';mapExample();observed=false;}else if(l.id==='ai-tokens'){q('#ai-corpus').value=defaultCorpus;renderTokens();}else{q('#ai-score').value='65';q('#ai-rule').value='70';renderClassifier();}q('#feedback').textContent='';status('รีเซ็ตแล้ว');return;}
 if(button.id==='ai-train'){if(l.id==='ai-tokens'){bigram=trainBigram(q('#ai-corpus').value);words=[];last='<START>';draws=0;renderTokens();status('ฝึกด้วยการนับคู่ Token แล้ว — Bigram ไม่ใช่ LLM');}else{trained=trainThreshold(data);trainedRevision=revision;renderClassifier();status('Training เสร็จ: เลือก threshold จากชุดฝึกแล้ว');}observed=true;}
 if(button.id==='ai-add'){if(data.some(p=>p.x===55&&p.y===1)){status('มีตัวอย่าง 55 → ผ่านแล้ว');return;}data.push({x:55,y:1});revision++;renderClassifier();status('เพิ่มข้อมูลแล้ว แต่ยังไม่ฝึกโมเดลใหม่');}
 if(button.id==='ai-next'){if(!bigram)throw Error('กดฝึก Bigram ก่อน');const options=distribution(bigram,last);if(!options.length||words.length>=30)return;if(draws===0)seed=42;draws++;seed=(Math.imul(seed,1664525)+1013904223)>>>0;last=sampleToken(options,seed/4294967296);if(last!=='<END>')words.push(last);renderTokens();status(last==='<END>'?'พบ <END> จบประโยคแล้ว':'เลือก Token จากความถี่คู่คำ · ตัวสุ่มกำหนดซ้ำได้ ไม่ใช่ LLM');observed=true;}
 if(button.id==='ai-restart'){words=[];last='<START>';draws=0;renderTokens();status('เริ่มประโยคใหม่ โดยใช้โมเดลเดิม');}
 }catch(error){status(error.message);}});
 if(l.id==='ai-map'){q('#ai-example').addEventListener('change',mapExample);mapExample();observed=false;}else if(l.id==='ai-tokens'){q('#ai-corpus').addEventListener('input',()=>status('ข้อความเปลี่ยนแล้ว ต้องฝึกใหม่ก่อนเปลี่ยนตัวเลือกของโมเดล'));renderTokens();}else{for(const id of ['#ai-score','#ai-rule'])q(id).addEventListener('input',()=>{try{renderClassifier();status('Inference: คำนวณด้วย threshold เดิม ไม่ได้ฝึกใหม่');}catch(error){status(error.message);}});renderClassifier();}
 return {dispose(){}};
}
